      <rect x={36} y={19} width={28} height={4} rx={1.5} fill="currentColor" opacity={0.4} />
      {[0, 1, 2].map((i) => (
        <rect
          key={i}
          x={36}
          y={32 + i * 11}
          width={40 - i * 8}
          height={4}
          rx={1.5}
          fill="currentColor"
          opacity={0.22}
