      <line x1={16} y1={12} x2={16} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <line x1={16} y1={62} x2={106} y2={62} stroke="currentColor" strokeWidth={1.25} opacity={0.4} />
      <path
        d="M16 48 L38 38 L58 44 L78 28 L106 34"
        stroke="currentColor"
        strokeWidth={1.25}
        strokeDasharray="3 4"
        opacity={0.45}
