      {[0, 1, 2, 3].map((i) => (
        <line
          key={i}
          x1={30 + i * 22}
          y1={62}
          x2={30 + i * 22}
          y2={65}
          stroke="currentColor"
          strokeWidth={1.25}
          opacity={0.3}
