'use client';

import type { ComponentProps } from 'react';
import { cn } from '../../utils';

/**
 * Loading states.
 *
 * Each skeleton is shaped like the thing it replaces - the ladder skeleton has
 * a spread row, the chart skeleton has an axis and a volume pane - so the
 * layout does not jump when real data lands and the eye already knows where to
 * look. A generic grey box would be cheaper and would cost a reflow every time.
 *
 * The pulse is opacity only, and stops under `prefers-reduced-motion`.
 */
export function Skeleton({ className, ...props }: ComponentProps<'div'>) {
  return (
    <div
      data-slot="skeleton"
      className={cn('bg-muted-foreground/15 animate-shimmer rounded-sm', className)}
      {...props}
    />
  );
}

/** Deterministic widths: random ones would re-roll on every render. */
const LADDER_WIDTHS = [62, 48, 74, 55, 68, 44, 80, 51, 66, 58, 72, 46];

export function OrderBookSkeleton({ depth = 8, className }: { depth?: number; className?: string }) {
  const row = (key: string, i: number, side: 'bid' | 'ask') => (
    <div key={key} className="flex items-center gap-2 px-2.5 py-[5px]">
      <Skeleton
        className={cn('h-2.5 flex-1', side === 'bid' ? 'bg-up/15' : 'bg-down/15')}
        style={{ maxWidth: `${LADDER_WIDTHS[i % LADDER_WIDTHS.length]}%` }}
      />
      <Skeleton className="h-2.5 w-10" />
      <Skeleton className="h-2.5 w-8" />
    </div>
  );

  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-10" />
        <Skeleton className="ml-auto h-2 w-8" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`a${i}`, i, 'ask'))}
      <div className="bg-muted my-0.5 flex items-center justify-between border-y px-2.5 py-2">
        <Skeleton className="h-2.5 w-16" />
        <Skeleton className="h-2.5 w-20" />
      </div>
      {Array.from({ length: depth }, (_, i) => row(`b${i}`, i + 3, 'bid'))}
    </div>
  );
}

export function TradeTapeSkeleton({ rows = 10, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-2 border-b px-2.5 py-1.5">
        <Skeleton className="h-2 w-8" />
        <Skeleton className="ml-auto h-2 w-10" />
        <Skeleton className="h-2 w-8" />
      </div>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="grid grid-cols-3 gap-2 px-2.5 py-[5px]">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-2.5 w-12 justify-self-end" />
          <Skeleton className="h-2.5 w-8 justify-self-end" />
        </div>
      ))}
    </div>
  );
}

/** Candle bars at varied heights around a baseline, plus axis and volume. */
const CANDLE_HEIGHTS = [38, 52, 44, 61, 49, 70, 57, 42, 66, 51, 74, 46, 59, 68, 40, 55, 63, 47];

export function CandleChartSkeleton({
  height = 320,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <div
      className={cn('flex w-full flex-col gap-2 p-2', className)}
      style={{ height }}
      aria-hidden="true"
    >
      <div className="flex min-h-0 flex-1 items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1"
            style={{ height: `${h}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex h-[16%] items-end gap-[3px] pr-14">
        {CANDLE_HEIGHTS.concat(CANDLE_HEIGHTS).map((h, i) => (
          <Skeleton
            key={i}
            className="min-w-[3px] flex-1 opacity-60"
            style={{ height: `${h * 0.7}%`, animationDelay: `${(i % 12) * 60}ms` }}
          />
        ))}
      </div>
      <div className="flex justify-between pr-14">
        {Array.from({ length: 6 }, (_, i) => (
          <Skeleton key={i} className="h-2 w-8" />
        ))}
      </div>
    </div>
  );
}

export function TableSkeleton({
  rows = 4,
  columns = 6,
  className,
}: {
  rows?: number;
  columns?: number;
  className?: string;
}) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      <div className="bg-muted flex gap-4 border-b px-2.5 py-2">
        {Array.from({ length: columns }, (_, i) => (
          <Skeleton key={i} className={cn('h-2', i === 0 ? 'w-14' : 'flex-1')} />
        ))}
      </div>
      {Array.from({ length: rows }, (_, r) => (
        <div key={r} className="flex gap-4 border-b px-2.5 py-2.5">
          {Array.from({ length: columns }, (_, i) => (
            <Skeleton key={i} className={cn('h-2.5', i === 0 ? 'w-14' : 'flex-1')} />
          ))}
        </div>
      ))}
    </div>
  );
}

export function WatchlistSkeleton({ rows = 6, className }: { rows?: number; className?: string }) {
  return (
    <div className={cn('flex flex-col', className)} aria-hidden="true">
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-center gap-2.5 border-b px-2.5 py-2">
          <Skeleton className="h-2.5 w-12" />
          <Skeleton className="h-4 w-14" />
          <Skeleton className="ml-auto h-2.5 w-12" />
          <Skeleton className="h-2.5 w-10" />
        </div>
      ))}
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { formatMoney, formatPercent } from '../../format';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument, Position } from '../../types';
import { cn, toArray } from '../../utils';
import { EmptyState } from './empty-state';
import { EmptyPositionsArt } from './illustrations';

export interface AllocationSlice {
  symbol: string;
  /** Signed market value. Negative is a short. */
  value: number;
  /** Share of gross exposure, 0-1. */
  weight: number;
  short: boolean;
}

export interface AllocationBarProps {
  positions: Position[];
  instrument?: Partial<Instrument>;
  /** Cash sleeve, so the bar shows how much of the account is actually at work. */
  cash?: number;
  /** Names beyond this are folded into an "Other" slice. */
  maxSlices?: number;
  /** Warn above this share of gross exposure in a single name. */
  concentrationLimit?: number;
  showLegend?: boolean;
  onSelect?: (symbol: string) => void;
  className?: string;
}

/**
 * Weights by gross exposure, largest first.
 *
 * Gross, not net: a book that is long 100k and short 100k is fully deployed
 * and carries the risk of both legs, while its net is zero. Netting here would
 * report an empty portfolio for a market-neutral account.
 */
export function allocate(
  positions: readonly Position[],
  cash = 0,
  maxSlices = 8,
): AllocationSlice[] {
  const sized = positions
    .map((p) => ({ symbol: p.symbol, value: p.quantity * p.markPrice }))
    .filter((p) => Number.isFinite(p.value) && p.value !== 0);

  const gross = sized.reduce((sum, p) => sum + Math.abs(p.value), 0) + Math.max(0, cash);
  if (gross === 0) return [];

  const ranked = sized.sort((a, b) => Math.abs(b.value) - Math.abs(a.value));
  const head = ranked.slice(0, maxSlices);
  const tail = ranked.slice(maxSlices);

  const slices: AllocationSlice[] = head.map((p) => ({
    symbol: p.symbol,
    value: p.value,
    weight: Math.abs(p.value) / gross,
    short: p.value < 0,
  }));

  if (tail.length) {
    const value = tail.reduce((sum, p) => sum + p.value, 0);
    const weight = tail.reduce((sum, p) => sum + Math.abs(p.value), 0) / gross;
    slices.push({ symbol: `Other (${tail.length})`, value, weight, short: value < 0 });
  }

  if (cash > 0) {
    slices.push({ symbol: 'Cash', value: cash, weight: cash / gross, short: false });
  }

  return slices;
}

/**
 * Where the account actually is, as one stacked bar plus a legend.
 *
 * Concentration is the risk this exists to surface: an account can look
 * healthy on every other panel - margin fine, P&L green - while sitting in a
 * single name. A slice over `concentrationLimit` is called out by name rather
 * than left for the user to work out from the geometry.
 */
export function AllocationBar({
  positions,
  instrument,
  cash,
  maxSlices = 8,
  concentrationLimit = 0.35,
  showLegend = true,
  onSelect,
  className,
}: AllocationBarProps) {
  const inst = useInstrument(instrument);
  const rows = toArray(positions);

  const { slices, concentrated } = useMemo(() => {
    const computed = allocate(rows, cash ?? 0, maxSlices);
    return {
      slices: computed,
      concentrated: computed.filter(
        (s) => s.symbol !== 'Cash' && !s.symbol.startsWith('Other') && s.weight > concentrationLimit,
      ),
    };
  }, [rows, cash, maxSlices, concentrationLimit]);

  if (slices.length === 0) {
    return (
      <EmptyState
        className={className}
        art={<EmptyPositionsArt />}
        title="Nothing allocated"
        description="Open a position and the weight it takes up in the account shows here."
      />
    );
  }

  return (
    <div data-slot="allocation-bar" className={cn('flex flex-col gap-2.5', className)}>
      <div
        className="bg-muted flex h-3 w-full overflow-hidden rounded-full"
        role="img"
        aria-label={slices
          .map((s) => `${s.symbol} ${formatPercent(s.weight, 1, false)}`)
          .join(', ')}
      >
        {slices.map((slice) => (
          <div
            key={slice.symbol}
            title={`${slice.symbol} — ${formatPercent(slice.weight, 1, false)}`}
            style={{ width: `${slice.weight * 100}%` }}
            className={cn(
              'h-full',
              slice.symbol === 'Cash'
                ? 'bg-muted-foreground/35'
                : slice.short
                  ? 'bg-down/70'
                  : 'bg-up/70',
              // A short slice is hatched as well as coloured, so the long/short
              // split survives greyscale and colour blindness.
              slice.short && 'bg-[repeating-linear-gradient(45deg,transparent,transparent_2px,rgba(0,0,0,.35)_2px,rgba(0,0,0,.35)_4px)]',
            )}
          />
        ))}
      </div>

      {concentrated.length > 0 && (
        <p className="text-down text-[11px]">
          {concentrated.map((s) => s.symbol).join(', ')}{' '}
          {concentrated.length === 1 ? 'is' : 'are'} over{' '}
          {formatPercent(concentrationLimit, 0, false)} of gross exposure.
        </p>
      )}

      {showLegend && (
        <ul className="flex flex-col gap-1">
          {slices.map((slice) => {
            const row = (
              <>
                <span className="flex items-center gap-1.5 truncate">
                  <span
                    aria-hidden
                    className={cn(
                      'size-2 shrink-0 rounded-[2px]',
                      slice.symbol === 'Cash'
                        ? 'bg-muted-foreground/35'
                        : slice.short
                          ? 'bg-down/70'
                          : 'bg-up/70',
                    )}
                  />
                  <span className="truncate font-medium">{slice.symbol}</span>
                  {slice.short && (
                    <span className="text-down text-[10px] font-semibold">SHORT</span>
                  )}
                </span>
                <span className="text-muted-foreground shrink-0 tabular-nums">
                  {formatMoney(Math.abs(slice.value), inst.currency)}
                  <span className="text-foreground ml-2 font-medium">
                    {formatPercent(slice.weight, 1, false)}
                  </span>
                </span>
              </>
            );

            return (
              <li key={slice.symbol}>
                {onSelect && slice.symbol !== 'Cash' && !slice.symbol.startsWith('Other') ? (
                  <button
                    type="button"
                    onClick={() => onSelect(slice.symbol)}
                    className="hover:bg-accent focus-visible:ring-ring flex w-full items-center justify-between gap-2 rounded px-1 py-0.5 text-xs outline-none focus-visible:ring-1"
                  >
                    {row}
                  </button>
                ) : (
                  <span className="flex w-full items-center justify-between gap-2 px-1 py-0.5 text-xs">
                    {row}
                  </span>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

/**
 * One execution. Distinct from an `Order`: an order is an instruction, a fill
 * is what actually happened to it, and a single order can produce many fills
 * at different prices. Reconciliation, cost basis and fee accounting all work
 * off fills, never off orders.
 */
export interface Fill {
  id: string;
  /** The order this execution belongs to, for grouping a partial sequence. */
  orderId?: string;
  symbol: string;
  time: number;
  side: Side;
  quantity: number;
  price: number;
  /** Commission or exchange fee, in the quote currency. Negative is a rebate. */
  fee?: number;
  /** `maker` rested and was hit; `taker` crossed the spread. Drives the fee. */
  liquidity?: 'maker' | 'taker';
  venue?: string;
}

'use client';

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
